__global__ __launch_bounds__(128) void
kernel_flashinfer_bf16_fp4_split_k2_reduce_pdl0(float* __restrict__ partials, __nv_bfloat16* __restrict__ C, int elements)
{
    const int tid = threadIdx.x;
    const int warp = make_warp_uniform(tid / 32);
    const int lane = tid % 32;


    const int bid = blockIdx.x;
    const int num_bids = gridDim.x;

    // === Task calls (dependency order) ===
    int idx = bid * 128 + tid;
    if (idx < elements) {
        float value = partials[idx] + partials[elements + idx];
        *(reinterpret_cast<__nv_bfloat16*>(C + idx) + (0)) = __float2bfloat16_rn(value);
    }
}

